// Инструмент андеррайтера: выпустить полис.
// Файл собирается из этого шаблона и шрифтов ap/fonts/*.b64 скриптом ap/build-function.ps1,
// результат уезжает в пользовательскую функцию issuePolicy коллекции policy.
// У коллекции есть зависимость pdfmake@0.3.11, поэтому встроенные функции здесь
// асинхронные - их надо ждать.
//
// Что выяснено спайком: пакет отдается переменной по code-name, require в песочнице нет,
// рабочий объект лежит в .default, шрифтов по умолчанию нет. Поэтому урезанный Roboto
// кладется в virtualfs из base64-константы. Регистрация идемпотентна: экземпляр
// библиотеки переиспользуется между вызовами.
//
// Вызывается только после подтверждения человеком - это настройка узла, не кода.

var FONT_REGULAR = "";
var FONT_BOLD = "";

var CARD_KEY = "card";
var RISK_KEY = "risk";
var ASSESSMENT_KEY = "assessment";
var COUNTER_KEY = "counter";
var SETTINGS_KEY = "settings";
var DB_INTEGRATION = "1000156248-my-joz";

var CARD_LABELS = [
  ["type", "Тип объекта"],
  ["area", "Площадь, м2"],
  ["wall_material", "Материал стен"],
  ["roof_material", "Материал кровли"],
  ["year", "Год постройки"],
  ["floors", "Этажность"],
  ["address", "Адрес"]
];

var RISK_LABELS = [
  ["heating", "Отопление"],
  ["security", "Охрана"],
  ["occupancy", "Проживание"]
];

var COVER_YEARS = 1;

function documentValue(document) {
  if (!document || typeof document !== "object") {
    return null;
  }
  return document.value && typeof document.value === "object" ? document.value : document;
}

// Выпускаем только по принятой заявке. Эскалация и отказ - не полис, а решение человека.
function canIssue(assessment) {
  if (!assessment || !assessment.decision) {
    return { ok: false, reason: "оценка риска не проводилась" };
  }
  if (assessment.decision !== "accepted") {
    return { ok: false, reason: "решение по заявке: " + assessment.decision };
  }
  return { ok: true, reason: null };
}

// Счетчик в базе, а не отметка времени: номера должны идти подряд и не повторяться.
function nextCounter(document) {
  var source = documentValue(document);
  var current = source && typeof source.value === "number" ? source.value : 0;
  return current + 1;
}

function formatNumber(counter, year) {
  var digits = String(counter);
  while (digits.length < 6) {
    digits = "0" + digits;
  }
  return "ПА-" + year + "-" + digits;
}

function pad(value) {
  return value < 10 ? "0" + value : String(value);
}

function policyDates(nowMs) {
  var issued = new Date(nowMs);
  var day = issued.getUTCDate();
  var month = issued.getUTCMonth();
  var year = issued.getUTCFullYear();
  var expires = new Date(Date.UTC(year + COVER_YEARS, month, day));
  return {
    issuedAt: pad(day) + "." + pad(month + 1) + "." + year,
    expiresAt: pad(expires.getUTCDate()) + "." + pad(expires.getUTCMonth() + 1) + "." + expires.getUTCFullYear(),
    year: year
  };
}

function money(value) {
  if (typeof value !== "number") {
    return "—";
  }
  return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}

function buildPolicy(card, risk, assessment, number, dates) {
  return {
    number: number,
    issuedAt: dates.issuedAt,
    expiresAt: dates.expiresAt,
    owner: card.owner || "—",
    card: card,
    risk: risk,
    reasons: assessment.reasons || [],
    basePrice: assessment.basePrice,
    price: assessment.price,
    totalK: assessment.totalK,
    sumInsured: assessment.sumInsured,
    franchise: assessment.franchise
  };
}

function rowsFrom(source, labels) {
  return labels.map(function (pair) {
    var value = source ? source[pair[0]] : null;
    return [
      { text: pair[1], color: "#6b7280" },
      { text: value === null || value === undefined || value === "" ? "—" : String(value), bold: true }
    ];
  });
}

function block(title, rows) {
  return [
    { text: title, fontSize: 9, color: "#6b7280", margin: [0, 0, 0, 4] },
    {
      table: { widths: ["35%", "65%"], body: rows },
      layout: "lightHorizontalLines",
      margin: [0, 0, 0, 14]
    }
  ];
}

// Расшифровка расчета: базовая премия, каждая надбавка и скидка отдельной строкой, итого.
function calculationRows(policy) {
  var rows = [[
    { text: "Базовая премия", color: "#6b7280" },
    { text: money(policy.basePrice) + " руб.", bold: true }
  ]];
  policy.reasons.forEach(function (item) {
    rows.push([
      { text: item.reason, color: "#6b7280" },
      { text: (item.k > 1 ? "надбавка " : "скидка ") + "x" + item.k, bold: true }
    ]);
  });
  rows.push([
    { text: "Итого к оплате", color: "#6b7280" },
    { text: money(policy.price) + " руб.", bold: true }
  ]);
  return rows;
}

function policyDocument(policy) {
  var content = [
    { text: "ПОЛИС СТРАХОВАНИЯ", fontSize: 18, bold: true, margin: [0, 0, 0, 4] },
    { text: "загородной недвижимости", fontSize: 12, margin: [0, 0, 0, 14] },
    {
      text: "№ " + policy.number + " от " + policy.issuedAt,
      bold: true,
      margin: [0, 0, 0, 2]
    },
    {
      text: "Срок страхования: с " + policy.issuedAt + " по " + policy.expiresAt,
      fontSize: 10,
      color: "#6b7280",
      margin: [0, 0, 0, 14]
    }
  ];

  content = content
    .concat(block("СТРАХОВАТЕЛЬ", [[
      { text: "Собственник", color: "#6b7280" },
      { text: policy.owner, bold: true }
    ]]))
    .concat(block("ОБЪЕКТ СТРАХОВАНИЯ", rowsFrom(policy.card, CARD_LABELS)))
    .concat(block("УСЛОВИЯ ЭКСПЛУАТАЦИИ", rowsFrom(policy.risk, RISK_LABELS)))
    .concat(block("ПОКРЫТИЕ", [
      [{ text: "Страховая сумма", color: "#6b7280" }, { text: money(policy.sumInsured) + " руб.", bold: true }],
      [{ text: "Франшиза", color: "#6b7280" }, { text: money(policy.franchise) + " руб.", bold: true }]
    ]))
    .concat(block("РАСЧЕТ ПРЕМИИ", calculationRows(policy)));

  content.push({
    text: "Страховая премия: " + money(policy.price) + " руб.",
    fontSize: 14,
    bold: true
  });
  content.push({
    text: "Документ сформирован автоматически, демонстрационный образец.",
    fontSize: 8,
    color: "#9ca3af",
    margin: [0, 16, 0, 0]
  });

  return {
    pageMargins: [40, 40, 40, 40],
    defaultStyle: { font: "Policy", fontSize: 11 },
    content: content
  };
}

async function renderPdf(policy) {
  var raw = typeof pdfmake !== "undefined" ? pdfmake : null;
  var lib = raw && raw.default ? raw.default : raw;
  if (!lib || typeof lib.createPdf !== "function") {
    throw new Error("pdfmake недоступен");
  }
  await lib.virtualfs.writeFileSync("policy-regular.ttf", FONT_REGULAR, "base64");
  await lib.virtualfs.writeFileSync("policy-bold.ttf", FONT_BOLD, "base64");
  await lib.addFonts({ Policy: { normal: "policy-regular.ttf", bold: "policy-bold.ttf" } });

  var buffer = await lib.createPdf(policyDocument(policy)).getBuffer();
  return typeof buffer.toString === "function"
    ? buffer.toString("base64")
    : Buffer.from(buffer).toString("base64");
}

// Бланк уезжает в прокси, а в канал идет только ссылка. Причин две: в песочнице нет
// объектного хранилища (Reactions.sendFile принимает url, а не содержимое), и реплика
// с восемнадцатью килобайтами base64 до канала не доезжает.
// Адрес и секрет лежат в базе документом settings, рядом с тарифом: в код их класть
// нельзя, они уедут в git.
async function publishPdf(settings, base64) {
  if (!settings || !settings.proxyUrl || !settings.policyToken) {
    await Log.error({ message: "Документ settings не настроен, бланк не опубликован" });
    return null;
  }
  var response = await Http.post({
    url: String(settings.proxyUrl).replace(/\/+$/, "") + "/api/policy",
    headers: { "X-Policy-Token": settings.policyToken, "Content-Type": "application/json" },
    body: { pdfBase64: base64 }
  });
  if (!response || response.status !== 200) {
    await Log.error({
      message: "Прокси не принял бланк",
      data: { status: response ? response.status : null }
    });
    return null;
  }
  return response.body && response.body.url ? response.body.url : null;
}

// Отправка файла в канал - украшение, а не обязанность: полис уже выпущен и записан
// в реестр. Поэтому падение здесь не должно ронять выпуск.
async function attachPdf(url, name) {
  try {
    await Reactions.sendFile({ url: url, name: name });
  } catch (error) {
    await Log.error({
      message: "Файл в канал не ушел",
      data: { error: error && error.message ? error.message : String(error) }
    });
  }
}

// Агенту возвращаем короткую сводку, странице - реквизиты и ссылку на бланк.
async function run() {
  var card = documentValue(await SessionDb.get({ documentKey: CARD_KEY })) || {};
  var risk = documentValue(await SessionDb.get({ documentKey: RISK_KEY })) || {};
  var assessment = documentValue(await SessionDb.get({ documentKey: ASSESSMENT_KEY }));

  var allowed = canIssue(assessment);
  if (!allowed.ok) {
    await Log.error({ message: "Полис не выпущен", data: allowed });
    return { issued: false, reason: allowed.reason };
  }

  var dates = policyDates(Date.now());
  var counter = nextCounter(await Db.get({ dbIntegration: DB_INTEGRATION, documentKey: COUNTER_KEY }));
  await Db.put({ dbIntegration: DB_INTEGRATION, documentKey: COUNTER_KEY, value: { value: counter } });

  var policy = buildPolicy(card, risk, assessment, formatNumber(counter, dates.year), dates);
  var base64 = await renderPdf(policy);

  var settings = documentValue(await Db.get({
    dbIntegration: DB_INTEGRATION,
    documentKey: SETTINGS_KEY
  }));
  policy.pdfUrl = await publishPdf(settings, base64);

  await Db.put({
    dbIntegration: DB_INTEGRATION,
    documentKey: "policy-" + policy.number,
    value: policy
  });

  await Reactions.sendText({
    text: "```json\n" + JSON.stringify({ stage: "issued", policy: policy }) + "\n```"
  });
  if (policy.pdfUrl) {
    await attachPdf(policy.pdfUrl, policy.number + ".pdf");
  }
  await Log.info({
    message: "Полис выпущен",
    data: { number: policy.number, price: policy.price, pdfUrl: policy.pdfUrl }
  });

  return {
    issued: true,
    pdfPublished: policy.pdfUrl !== null,
    number: policy.number,
    price: policy.price,
    sumInsured: policy.sumInsured,
    franchise: policy.franchise,
    issuedAt: policy.issuedAt,
    expiresAt: policy.expiresAt
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    canIssue: canIssue,
    nextCounter: nextCounter,
    formatNumber: formatNumber,
    policyDates: policyDates,
    money: money,
    buildPolicy: buildPolicy,
    policyDocument: policyDocument
  };
} else {
  return run();
}
